for attempt := 1; ; attempt++ {
    resp, err := call(ctx)
    if err == nil || !transient(err) || attempt >= maxAttempts {
        return resp, err
    }
    interval := math.Min(cap, base*math.Pow(2, float64(attempt-1)))
    d := time.Duration(rand.Float64() * float64(interval))   // full jitter
    select {
    case <-time.After(d):
    case <-ctx.Done():
        return resp, ctx.Err()
    }
}
